import {MAPS,AGENTS,recommend} from './recommender.js';
export function recommendationView(profile,history,map,filter,model){
 const ranked=recommend(history,map,profile.role,model,filter),top=ranked.slice(0,3);
 const pct=n=>(100*n).toFixed(1)+'%';
 return `<section class="pick-controls panel"><div><span class="badge">PERSONALISED AGENT PICKS</span><h2>Choose your battleground.</h2><p class="muted">${profile.id} · ${history.length} recent matches · preferred role: ${profile.role}</p></div><div class="pick-selects"><label for="map-select">Map<select id="map-select">${MAPS.map(m=>`<option ${m===map?'selected':''}>${m}</option>`).join('')}</select></label><label for="role-filter">Agent role<select id="role-filter">${['All','Duelist','Controller','Initiator','Sentinel'].map(r=>`<option ${r===filter?'selected':''}>${r}</option>`).join('')}</select></label></div></section><div class="recommendation-context"><div><span class="eyebrow">${map.toUpperCase()} / YOUR SHORTLIST</span><h2>${top.length===1?'Your available pick':`Your top ${top.length} picks`}</h2></div><span class="muted">${ranked.length} candidates evaluated · synthetic model</span></div><section class="pick-grid">${top.map((agent,i)=>{
 const signal=[...agent.signals].sort((a,b)=>b.value-a.value)[0];
 const why=signal.value>0?`${signal.name} is the strongest positive model contribution for this candidate.`:'The combined model signals place this candidate on your shortlist.';
 return `<article class="pick-card ${i===0?'first-pick':''}"><div class="pick-top"><span class="badge">${i===0?'TOP MODEL PICK':'ALTERNATIVE '+i}</span><span class="pick-number">0${i+1}</span></div><div class="agent-name"><h3>${agent.name}</h3><span>${agent.role}</span></div><div class="pick-probability">${pct(agent.probability)}<small>estimated win probability<br>in the synthetic simulation</small></div><div class="bar"><i style="width:${agent.probability*100}%"></i></div><p>${why}</p><div class="pick-evidence"><b>${agent.evidence}</b><span>${agent.experience} prior matches on this agent · ${agent.mapMatches} on ${map}</span><span>${model.support[map][agent.name]} training examples for this map–agent pair</span></div>${agent.experience<5?'<p class="sparse-note">Explore cautiously: this pick relies mainly on patterns from other synthetic players.</p>':''}<details><summary>Why this recommendation?</summary><p class="muted">Actual logistic-model contributions, relative to the intercept. Positive values raise the score; these are log-odds, not percentage-point effects.</p>${agent.signals.map(s=>`<div class="signal-row"><span>${s.name}</span><b class="${s.value>=0?'positive':'negative'}">${s.value>=0?'+':''}${s.value.toFixed(3)}</b></div>`).join('')}<p class="muted">Contributions describe model behaviour, not causation.</p></details></article>`}).join('')}</section><div class="wide-note">Demo only: learned from synthetic match outcomes, not live Riot data or the current agent meta. A higher score does not guarantee that changing agents improves your win rate. Small score differences should not be treated as decisive.</div><section class="panel"><div class="section-head"><h2>The ML behind your picks</h2><span class="badge">LOGISTIC REGRESSION</span></div><p><b>Map + candidate agent + prior agent history + preferred role → learned win estimate → ranked shortlist.</b></p><p>One trained classifier evaluates each of the ${AGENTS.length} supported agents. Change the map or demo ID to run it again. Maps and agents are a demo subset, not a claim about the current competitive rotation.</p><details><summary>Training and evaluation</summary><div class="evaluation-grid"><div><strong>${model.trainingRows.toLocaleString()}</strong><span>training matches / ${model.trainingPlayers} players</span></div><div><strong>${model.testRows.toLocaleString()}</strong><span>held-out matches / ${model.testPlayers} different players</span></div><div><strong>${model.metrics.logLoss.toFixed(3)}</strong><span>test log loss · baseline ${model.baseline.logLoss.toFixed(3)}</span></div><div><strong>${model.metrics.brier.toFixed(3)}</strong><span>Brier score · baseline ${model.baseline.brier.toFixed(3)}</span></div></div><p class="muted">Lower log loss and Brier score are better. The baseline always predicts the training win rate. Features are calculated from matches before each labelled outcome, and test players are separate from training players. Results only validate this simulation; recommendation quality and probability calibration for real players are untested.</p><p class="muted">The generator deliberately simulates map–agent preferences. Historical outcomes cannot reveal how the same match would have ended with a different agent. Real recommendations require permitted data and further evaluation.</p></details></section>`;
}
